/* CAN receive mailbox for Id on Bus (1=A/FDCAN1, 2=B/FDCAN2).
 * Fresh is true for one step when a new frame arrived; Dlc/bytes hold the
 * latest payload otherwise. */
uint8_t buf[8] = {};
uint32_t seq = 0;
const int dlc = platform_can_rx(static_cast<uint8_t>(Bus),
                                static_cast<uint32_t>(Id), buf, &seq);
Fresh = (seq != LastSeq);
LastSeq = static_cast<float>(seq);
if (dlc > 0) {
    Dlc = static_cast<float>(dlc);
    D0 = buf[0]; D1 = buf[1]; D2 = buf[2]; D3 = buf[3];
    D4 = buf[4]; D5 = buf[5]; D6 = buf[6]; D7 = buf[7];
} else {
    Dlc = 0.0f;
}

/* All voltage sense channels from the MAX22530 isolated ADC, filtered. */
V_U  = rte::Volts(platform_phase_voltage_u());
V_V  = rte::Volts(platform_phase_voltage_v());
V_W  = rte::Volts(platform_phase_voltage_w());
V_Dc = rte::Volts(platform_get_dc_link_voltage());

const float cos_theta = cosf(Theta);
const float sin_theta = sinf(Theta);
V_Alpha = V_D * cos_theta - V_Q * sin_theta;
V_Beta = V_D * sin_theta + V_Q * cos_theta;

/* User digital output. Pin 1..4 -> USER_DOUT_1..4, 5 -> green LED,
 * 6 -> orange LED (see platform_api.h). */
platform_digital_write(static_cast<uint8_t>(Pin), In);

Angle += RateRadPerS * Dt;
if (Angle >= 6.28318530718f) Angle -= 6.28318530718f;
ThetaElec = Angle;

/* PI with clamping + back-calculation anti-windup.
 * Dimensionless throughout: implicit unit extraction/injection handles any
 * physical-quantity wiring at the binding sites. */
const float error = Setpoint - Measurement;
Integral += error * Dt;

float raw_output = Kp * error + Ki * Integral;

/* Dynamic limit derived from DC-link voltage, matching the base image's
 * VectorPIController convention: max = Vdc/sqrt(3) * 0.95. */
const float vdc = platform_get_dc_link_voltage();
const float dynamic_max = (vdc / 1.7320508075688772f) * 0.95f;
const float max_limit = (dynamic_max < OutputMax) ? dynamic_max : OutputMax;
const float min_limit = (-dynamic_max > OutputMin) ? -dynamic_max : OutputMin;

float limited_output = raw_output;
if (limited_output > max_limit) limited_output = max_limit;
if (limited_output < min_limit) limited_output = min_limit;

/* Back-calculation anti-windup, scaled by AwGain (0 disables; 1.0 matches
 * the base-image VectorPIController). */
if (Ki > 0.0001f && Kp > 0.0001f && AwGain > 0.0f) {
    const float excess = raw_output - limited_output;
    Integral -= excess * Dt * AwGain / (Kp * Ki);
}

Output = limited_output;

/* Dual throttle channels, normalized [0..1] by the base-image driver
 * (KV calibration Hw.ThrA/B.MinV/MaxV).  Both read 0 and Valid is false
 * while the channels disagree beyond the plausibility tolerance. */
A = platform_get_throttle_a();
B = platform_get_throttle_b();
Valid = platform_get_throttle_valid();

/* Motor + board temperatures from the base-image ApplicationSensors driver.
 * NAN while a channel is disabled or out of range (open/short). */
T_Motor = rte::Celsius(platform_get_motor_temperature());
T_Inv1  = rte::Celsius(platform_get_inverter_temperature(0));
T_Inv2  = rte::Celsius(platform_get_inverter_temperature(1));
T_Inv3  = rte::Celsius(platform_get_inverter_temperature(2));

/* Filtered derivative: Out ~= d(In)/dt, low-passed at Fc [Hz] to keep
 * sampling noise out of the estimate (Fc <= 0 disables filtering).
 * Prev/OutState are persistent state (leave at graph defaults). */
const float raw = (In - Prev) / Dt;
Prev = In;
if (Fc > 0.0f) {
    const float alpha = 1.0f / (1.0f + 1.0f / (6.28318530718f * Fc * Dt));
    OutState += alpha * (raw - OutState);
} else {
    OutState = raw;
}
Out = OutState;

/* Mechanical angle [rad] and speed [rpm] from the base-image encoder driver. */
Theta = platform_get_encoder_angle_latest() * 0.01745329251f;  // deg -> rad
Omega = platform_get_motor_rpm();

/* Guard: with no usable DC-link reading (bus off / sensor not ready) the
 * inverse-Clarke divide would produce inf/NaN duties.  Emit neutral. */
if (!(V_Dc.in(au::volts) > 1.0f)) {
    Duty_A = 50.0f;
    Duty_B = 50.0f;
    Duty_C = 50.0f;
} else {

/* Clamp the alpha/beta voltage vector to the linear SVM limit.
 * The maximum line-to-neutral voltage magnitude for linear modulation is
 * Vdc / sqrt(3).  Use a small margin to stay away from the overmodulation
 * boundary. */
const float sqrt3 = 1.7320508075688772f;
const float v_max_linear = (V_Dc.in(au::volts) / sqrt3) * 0.95f;
float valpha = V_Alpha.in(au::volts);
float vbeta  = V_Beta.in(au::volts);
const float v_albe_sq = valpha * valpha + vbeta * vbeta;
if (v_albe_sq > v_max_linear * v_max_linear && v_albe_sq > 1e-12f) {
    const float scale = v_max_linear / sqrtf(v_albe_sq);
    valpha *= scale;
    vbeta  *= scale;
}

/* Inverse Clarke: alpha/beta -> A/B/C. */
const float v_a = valpha / V_Dc.in(au::volts);
const float v_b = (-0.5f * valpha + 0.86602540378f * vbeta) / V_Dc.in(au::volts);
const float v_c = (-0.5f * valpha - 0.86602540378f * vbeta) / V_Dc.in(au::volts);

float v_min = v_a;
if (v_b < v_min) v_min = v_b;
if (v_c < v_min) v_min = v_c;

float v_max = v_a;
if (v_b > v_max) v_max = v_b;
if (v_c > v_max) v_max = v_c;

const float v_offset = 0.5f * (v_min + v_max);

/* Convert to percent duty and clamp.  Linear SVM stays roughly in
 * [21%, 79%]; clamping to [0,100] only catches numerical edge cases. */
float duty_a_pct = 50.0f + 50.0f * (v_a - v_offset);
float duty_b_pct = 50.0f + 50.0f * (v_b - v_offset);
float duty_c_pct = 50.0f + 50.0f * (v_c - v_offset);

if (duty_a_pct < 0.0f) duty_a_pct = 0.0f; else if (duty_a_pct > 100.0f) duty_a_pct = 100.0f;
if (duty_b_pct < 0.0f) duty_b_pct = 0.0f; else if (duty_b_pct > 100.0f) duty_b_pct = 100.0f;
if (duty_c_pct < 0.0f) duty_c_pct = 0.0f; else if (duty_c_pct > 100.0f) duty_c_pct = 100.0f;

Duty_A = duty_a_pct;
Duty_B = duty_b_pct;
Duty_C = duty_c_pct;

}

/* Rate-limited reference follower: Out tracks In at max Rate units/sec.
 * On control start Value resets to the graph default, so references ramp
 * smoothly from zero instead of stepping. */
const float target = In;
const float step = Rate * Dt;
float v = Value;
if (target > v + step) {
    v += step;
} else if (target < v - step) {
    v -= step;
} else {
    v = target;
}
Value = v;
Out = Value;

/* Wrap the mechanical encoder angle to [0, 2*pi). */
const float two_pi = 6.28318530718f;
float theta = fmodf(ThetaMech, two_pi);
if (theta < 0.0f) theta += two_pi;

/* Electrical angle = offset (elec deg) + sign * encoder_angle * (Poles / 2).
 * Matches the base-image FocController convention. */
constexpr float DEG_TO_RAD = 0.01745329251f;
float elec = OffsetDeg * DEG_TO_RAD + EncoderSign * theta * Poles * 0.5f;

/* Wrap the electrical angle to [0, 2*pi). */
elec = fmodf(elec, two_pi);
if (elec < 0.0f) elec += two_pi;

ThetaElec = elec;

float iu_f = 0.0f;
float iv_f = 0.0f;
float iw_f = 0.0f;
if (platform_get_phase_currents(&iu_f, &iv_f, &iw_f)) {
    /* Keep raw sensor polarity available for general telemetry, while FOC
     * graphs enable inversion for this hardware's current-sensor wiring. */
    const float polarity = InvertPolarity ? -1.0f : 1.0f;
    I_A = rte::Amperes(polarity * iu_f);
    I_B = rte::Amperes(polarity * iv_f);
    I_C = rte::Amperes(polarity * iw_f);
}

const float cos_theta = cosf(Theta);
const float sin_theta = sinf(Theta);
I_D = I_Alpha * cos_theta + I_Beta * sin_theta;
I_Q = -I_Alpha * sin_theta + I_Beta * cos_theta;

platform_telemetry_log_f32("cg_iu_a", I_A.in(au::amperes));
platform_telemetry_log_f32("cg_iv_a", I_B.in(au::amperes));
platform_telemetry_log_f32("cg_iw_a", I_C.in(au::amperes));

V_A = V_Alpha;
V_B = -0.5f * V_Alpha + 0.86602540378f * V_Beta;
V_C = -0.5f * V_Alpha - 0.86602540378f * V_Beta;

/* CAN transmit, rate-limited by wall clock: sends when 1000/Rate ms have
 * elapsed since the previous send (Rate <= 0 sends every step).
 * D0..D7 = payload bytes (unconnected = 0), Dlc = how many of the 8 to
 * send, Ext: 0 std / 1 ext. */
const uint32_t period_ms = (Rate > 0.0f) ? static_cast<uint32_t>(1000.0f / Rate) : 0U;
const uint32_t now_ms = platform_millis();
if (period_ms == 0U || (now_ms - static_cast<uint32_t>(LastMs)) >= period_ms) {
    LastMs = static_cast<float>(now_ms);
    const uint8_t b[8] = {
        static_cast<uint8_t>(D0), static_cast<uint8_t>(D1),
        static_cast<uint8_t>(D2), static_cast<uint8_t>(D3),
        static_cast<uint8_t>(D4), static_cast<uint8_t>(D5),
        static_cast<uint8_t>(D6), static_cast<uint8_t>(D7),
    };
    uint8_t n = static_cast<uint8_t>(Dlc);
    if (n > 8) n = 8;
    platform_can_send(static_cast<uint8_t>(Bus), static_cast<uint32_t>(Id),
                      Ext > 0.5f, b, n);
}

/* Electrical frequency estimate: f_e = |rpm| / 60 * (poles / 2), low-passed.
 * NaN/invalid guards fall back to zero so the sequencer stays in mode 0. */
float poles = Poles;
if (!(poles >= 2.0f)) poles = 10.0f;

float f_raw = fabsf(Omega_Mech) / 60.0f * (poles * 0.5f);
if (!std::isfinite(f_raw)) f_raw = 0.0f;

Dir = (Omega_Mech >= 0.0f) ? 1.0f : -1.0f;

if (Fc > 0.0f && Dt > 0.0f) {
    const float alpha = 1.0f / (1.0f + 1.0f / (6.28318530718f * Fc * Dt));
    State += alpha * (f_raw - State);
} else {
    State = f_raw;
}
F_Elec = State;

/* Railway-style modulation sequencer (mode ladder + boundary table).
 *
 * v1 ladder: 0 = carrier (SVPWM), 1 = six-step.  The ladder is data: each
 * boundary has an enter threshold, an exit threshold (hysteresis), a minimum
 * dwell, and a transition type (TransMs == 0: hard phase-locked switch;
 * TransMs > 0: timed linear crossfade).  Extending the ladder (sync-15/12/9/
 * 7/5/3, overmodulation, ...) adds boundary params, not new logic.
 *
 * Continuity at the switch is the modulators' job (gain/phase-matched arm),
 * not this node's.  This node only decides WHEN and reports From/To/Blend.
 *
 * Blend is the output weight of the higher ladder slot: 0 = mode 0 duties,
 * 1 = mode 1 duties.  Steady state: Blend == CurMode. */

const bool en = Enable;

if (!en || !(Dt > 0.0f)) {
    CurMode = 0.0f;
    DwellT = 0.0f;
    TransT = 0.0f;
    BlendS = 0.0f;
    ModeFrom = 0.0f;
    ModeTo = 0.0f;
    Blend = 0.0f;
    Mode = 0.0f;
    TransActive = false;
} else if (TransT > 0.0f) {
    /* Transition in progress. */
    TransActive = true;
    if (TransMs > 0.0f) {
        const float dir = (ModeTo > ModeFrom) ? 1.0f : -1.0f;
        BlendS += dir * Dt / (TransMs * 0.001f);
        if (BlendS > 1.0f) BlendS = 1.0f;
        if (BlendS < 0.0f) BlendS = 0.0f;
        if ((dir > 0.0f && BlendS >= 1.0f) || (dir < 0.0f && BlendS <= 0.0f)) {
            TransT = 0.0f;
        }
    } else {
        /* Hard switch: the incoming modulator armed on the ModeTo edge last
         * step and is gain/phase-matched; switch now. */
        BlendS = ModeTo;
        TransT = 0.0f;
    }
    if (TransT == 0.0f) {
        CurMode = ModeTo;
        ModeFrom = CurMode;
        ModeTo = CurMode;
        TransActive = false;
    }
    Blend = BlendS;
    Mode = CurMode;
} else {
    /* Steady state: watch the adjacent boundary. */
    ModeFrom = CurMode;
    ModeTo = CurMode;
    BlendS = CurMode;
    Blend = BlendS;
    Mode = CurMode;
    TransActive = false;

    if (CurMode < 0.5f) {
        DwellT = (F_Elec >= FEnterHz) ? (DwellT + Dt) : 0.0f;
        if (DwellT * 1000.0f >= MinDwellMs) {
            DwellT = 0.0f;
            TransT = Dt;
            ModeFrom = 0.0f;
            ModeTo = 1.0f;
        }
    } else {
        DwellT = (F_Elec <= FExitHz) ? (DwellT + Dt) : 0.0f;
        if (DwellT * 1000.0f >= MinDwellMs) {
            DwellT = 0.0f;
            TransT = Dt;
            ModeFrom = 1.0f;
            ModeTo = 0.0f;
        }
    }
}

/* Duty routing for the modulation ladder: out = (1-Blend)*A + Blend*B, then
 * sanitize.  A non-finite duty (NaN/inf from any upstream path) becomes the
 * 50% neutral point so PwmOut can never emit NaN. */
auto san = [](float x) -> float { return std::isfinite(x) ? x : 50.0f; };
const float w = (Blend < 0.0f) ? 0.0f : ((Blend > 1.0f) ? 1.0f : Blend);

Duty_A = san((1.0f - w) * A_A + w * B_A);
Duty_B = san((1.0f - w) * A_B + w * B_B);
Duty_C = san((1.0f - w) * A_C + w * B_C);

/* Synchronous n-pulse PWM (synchronized sampled sine) - the ladder's
 * intermediate sync mode.
 *
 * The pattern is locked to the rotor angle: duties follow a sine referenced
 * to Theta_E + atan2(V_Q, V_D), slot-averaged over 2*pi/N slots, with N
 * chosen from the chopping-rate budget (largest odd multiple of 3 with
 * N*f_e <= FAsyncHz).  The timer keeps chopping at the async carrier, so
 * phase current ripple stays carrier-bounded at ANY fundamental; only the
 * average staircase is rotor-locked.  At high N (low f_e) this converges to
 * async SVPWM; as f_e rises N steps down and switching becomes visibly
 * synchronous.
 *
 * NOT six-step: full-rail plateaus on a low-L motor at low f_e let phase
 * current free-run between edges (bench: 250 A at 20 Hz).  Square-wave SHE
 * patterns belong to the top of the ladder (voltage ceiling), later.
 *
 * Contract: ModeId-gated, holds 50% neutral otherwise; vdc < 1 V -> 50%. */

const float vdc = V_Dc.in(au::volts);
const bool running = (ModeId == ModeFrom) || (ModeId == ModeTo);

if (!running || !(vdc > 1.0f) || !(F_Elec > 0.01f)) {
    Duty_A = 50.0f;
    Duty_B = 50.0f;
    Duty_C = 50.0f;
} else {
    const float vd = V_D.in(au::volts);
    const float vq = V_Q.in(au::volts);

    /* Rotor-locked reference angle: theta_e + smooth dq phase offset. */
    const float ang = Theta_E + atan2f(vq, vd);

    /* Commanded magnitude relative to the SVPWM linear max (vdc/sqrt(3));
     * the 2/sqrt(3) factor makes the phase fundamental match SVPWM's. */
    float m = sqrtf(vd * vd + vq * vq) / (vdc * 0.57735026919f);
    if (m > 1.0f) m = 1.0f;
    if (m < 0.0f) m = 0.0f;
    const float g = 1.1547005384f * m;  /* 2/sqrt(3) * m */

    /* Pulse number: largest odd multiple of 3 within the chopping budget.
     * Steps up freely, steps down with margin (hysteresis). */
    const float ratio = FAsyncHz / F_Elec;
    int n_new = 3 * (2 * (int)(ratio / 6.0f) + 1);
    if (n_new < 3) n_new = 3;
    if (n_new > 999) n_new = 999;
    int N = (NState > 0.5f) ? (int)NState : n_new;
    if (n_new > N) N = n_new;
    else if (n_new < N - 6) N = n_new;
    NState = (float)N;
    N_Pulses = (float)N;

    const float two_pi = 6.28318530718f;
    const float h = two_pi / (float)N;
    const float sinc = (h > 1.0e-6f) ? (sinf(0.5f * h) / (0.5f * h)) : 1.0f;

    /* Slot-averaged reference: average value of the phase reference over
     * each slot, so the held duty matches the slot's mean.  The reference
     * is cos (NOT sin): SVPWM's phase A follows valpha = |V|*cos(phi), so
     * phase A must peak when the vector points at +alpha.  Using sin here
     * rotated the applied vector 90 deg into the d-axis and blew up the
     * bench (id > 400 A, bus collapse). */
    auto slotavg = [&](float phase) -> float {
        const float slot = floorf(phase / h);
        return cosf((slot + 0.5f) * h) * sinc;
    };

    auto duty = [](float d) -> float {
        if (d < 0.0f) return 0.0f;
        if (d > 100.0f) return 100.0f;
        return d;
    };

    Duty_A = duty(50.0f + 50.0f * g * slotavg(ang));
    Duty_B = duty(50.0f + 50.0f * g * slotavg(ang - 2.09439510239f));
    Duty_C = duty(50.0f + 50.0f * g * slotavg(ang + 2.09439510239f));
}
